import fs from 'node:fs';
import assert from 'node:assert/strict';
const read = (p) => fs.readFileSync(p, 'utf8');
const controller = read('backend/controllers/chatController.js');
const migration = read('supabase/migrations/20260907173000_chat_concurrency_integrity.sql');
const client = read('src/services/chatApi.ts');
const auth = read('src/context/AuthContext.tsx');
const app = read('src/App.tsx');
assert.match(migration, /kayad_append_chat_message[\s\S]*?FOR UPDATE/);
assert.match(migration, /kayad_mark_chat_seen[\s\S]*?FOR UPDATE/);
assert.match(migration, /WITH ORDINALITY/);
assert.match(controller, /kayad_append_chat_message/);
assert.match(controller, /CHAT_MESSAGE_PERSISTENCE_UNCONFIRMED/);
assert.match(controller, /emit\("newMessage"/);
assert.match(client, /pendingMessageKeys/);
assert.match(client, /Idempotency-Key/);
assert.match(client, /persisted\.id/);
assert.match(auth, /getMe\(\)/);
assert.match(auth, /catch\(\(\) => \{ \/\* not authenticated — user stays null \*\//);
assert.match(app, /if \(!isAuth\)[\s\S]*?loginPathFor\(location\)/);
console.log('PASS: atomic chat append/read-seen RPCs, persisted-response gate, stable idempotency key, and auth redirect path are present.');
console.log('NOTE: live PostgreSQL/two-account API and Socket.IO tests remain outstanding; this validator does not certify them.');
